  "ruleText": "اندرونی JSON کو برابر کرنے کا کوئی ایک درست طریقہ نہیں، اس لیے یہ صفحہ اپنا اصول چھپانے کے بجائے بیان کرتا ہے۔ اندرونی آبجیکٹ نقطہ-راستہ کالم بنتے ہیں: {\"address\":{\"city\":\"Lahore\"}} address.city نامی کالم بنتا ہے۔ سادہ اقدار کی فہرست ایک خانہ بنتی ہے '; ' سے جڑی۔ آبجیکٹ رکھنے والی فہرست ایک خانے میں مختصر JSON متن کے طور پر رہتی ہے — ایک اندراج ریکارڈ ہمیشہ ایک نتیجہ سطر رہتا ہے، اس لیے اندرونی فہرستیں کبھی اضافی سطروں میں نہیں پھٹتیں۔ کالم تمام ریکارڈز میں ہر برابر چابی کا مجموعہ ہیں، پہلی-نظر ترتیب میں؛ جس ریکارڈ میں چابی نہ ہو اسے خالی خانہ ملتا ہے۔ اعداد اور درست/غلط جیسے JSON میں آتے ہیں ویسے لکھے جاتے ہیں، اور null خالی خانہ بنتا ہے۔",
